# 07_si_figures2.R: SI figures S4 (species contributions), S5 (similar LCBD, contrasting retention), S6 (sensitivity: stems vs trees)
source("fig_common.R"); prof <- readRDS("out/retention_profiles.rds"); sp <- readRDS("out/bci_matrices.rds")$spp; q5 <- read.csv("tables/q5_species_contributions_swamp_vs_rest.csv") |> left_join(sp[, c("sp", "Latin")], by = c("species" = "sp"))
qoh <- read.csv("tables/q5_occupancy_heterogeneity_by_habitat.csv")
# ---------- S4: species contributions to local distinctiveness
topsp <- function(k, ty, n = 12, yr = "1985_tree") { d <- q5 |> filter(set == yr, order == k, type == ty, group == "swamp") |> arrange(desc(contribution)) |> head(n); d$lab <- factor(sprintf("%s (%d)", sub("^(.)[a-z]+ ", "\\1. ", d$Latin), d$region_occupancy), rev(sprintf("%s (%d)", sub("^(.)[a-z]+ ", "\\1. ", d$Latin), d$region_occupancy))); d$k <- k; d }
tt <- bind_rows(topsp(2, "relative"), topsp(40, "relative")) |> pivot_longer(c(occupancy_part, heterogeneity_part)); tt$name <- factor(tt$name, c("occupancy_part", "heterogeneity_part"), c("Restricted occupancy", "Numerical dominance (shared species)"))
pl <- lapply(c(2, 40), function(k) ggplot(tt[tt$k == k, ], aes(value, lab, fill = name)) + geom_col(width = .7) + scale_fill_manual(values = c(pal[["petrol"]], pal[["orange"]]), name = NULL) + labs(x = "Mean contribution to swamp-quadrat LCZD(relative)", y = NULL, title = sprintf("Order k = %d", k), subtitle = if (k == 2) "Species (regional occupancy, quadrats)" else NULL) + th() + theme(legend.position = "bottom"))
ti <- topsp(2, "incidence") |> mutate(name = "Occurrence"); pI <- ggplot(ti, aes(contribution, lab)) + geom_col(width = .7, fill = pal[["sage"]]) + labs(x = "Mean contribution to swamp-quadrat incidence dissimilarity (richness units), k = 2", y = NULL, title = "Incidence") + th()
oh <- qoh |> filter(set %in% c("1985_tree", "2015_tree"), type == "relative") |> mutate(year = sub("_.*", "", set), Hshare = heterogeneity_part / expected_dissimilarity, habitat = factor(habitat, names(hab_col)))
pO <- ggplot(oh, aes(order, Hshare, colour = habitat, linetype = year, group = interaction(habitat, year))) + geom_line(linewidth = .5) + geom_point(size = .8) + scale_colour_manual(values = hab_col, labels = hab_lab, name = NULL) + scale_x_continuous(breaks = c(2, 10, 40)) + labs(x = "Zeta order k", y = "Share of local dissimilarity due to\nabundance heterogeneity of shared species", linetype = "Census") + th() + theme(legend.position = "right")
sv(((pl[[1]] | pl[[2]]) / (pI | pO)) + plot_annotation(tag_levels = "A"), "FigureS4_species_contributions", 8.4, 8.6)
# ---------- S5: similar LCBD, contrasting retention
bins <- read.csv("tables/q2_LCBD_bins_retention_range.csv") |> filter(set == "1985_tree", bin_LCBD_range_pct <= 20); bins$variable <- factor(bins$variable, c("T_rel", "T_plus_rel", "T_occ", "T_plus_occ"), c("T (abundance)", "T+ (abundance)", "T (occurrence)", "T+ (occurrence)"))
pb <- ggplot(bins, aes(bin_LCBD_median * 1e3)) + geom_ribbon(aes(ymin = bin_min, ymax = bin_max), fill = pal[["petrol"]], alpha = .25) + facet_wrap(~variable, scales = "free", nrow = 1) + labs(x = expression("Median LCBD of the bin (matching representation)" ~ (10^-3)), y = "Range of retention order among 25 quadrats\nwith adjacent LCBD (bins spanning <= 20% of the median)") + th()
d85 <- S[S$set == "1985_tree", ]; ex <- list(c("x005_y024", "x014_y012"), c("x020_y012", "x023_y005")); ord <- 1:640
mkp <- function(pairs, type, P) bind_rows(lapply(seq_along(pairs), function(i) bind_rows(lapply(pairs[[i]], function(e) data.frame(k = ord, v = P[e, ord], quad = e, pair = paste("Pair", i), type = type)))))
pr <- bind_rows(mkp(ex, "Relative abundance", prof[["1985_tree"]]$relative), mkp(ex, "Occurrence", prof[["1985_tree"]]$occurrence)); pr$hab <- d85$habitat[match(pr$quad, d85$quad)]; mi <- match(pr$quad, d85$quad); pr$lab <- sprintf("%s (%s): LCBD %.2f abund., %.2f occ.; T %.1f abund., %.1f occ.", pr$quad, hab_lab[as.character(pr$hab)], 1e3 * d85$LCBD_hel[mi], 1e3 * d85$LCBD_hel_occ[mi], d85$T_rel[mi], d85$T_occ[mi])
pp <- ggplot(pr, aes(k, v, colour = lab)) + geom_line(linewidth = .6) + facet_grid(type ~ pair) + scale_x_log10(breaks = c(1, 2, 5, 20, 100, 640)) + scale_colour_manual(values = c(pal[["orange"]], pal[["sage"]], "#8F4410", pal[["petrol"]]), name = NULL) + labs(x = "Zeta order k", y = "Shared composition (conditional zeta)") + th() + theme(legend.position = "bottom", legend.text = element_text(size = 5)) + guides(colour = guide_legend(ncol = 2))
sv((pb / pp) + plot_layout(heights = c(1, 1.8)) + plot_annotation(tag_levels = "A"), "FigureS5_matched_LCBD_contrasting_retention", 7.6, 8)
# ---------- S6: stems versus tree records
tr <- S[S$set == "1985_tree", ]; st <- S[S$set == "1985_stem", ]; tr15 <- S[S$set == "2015_tree", ]; st15 <- S[S$set == "2015_stem", ]
cmp <- bind_rows(data.frame(year = 1985, habitat = tr$habitat, tree = tr$LCBD_hel * 1e3, stem = st$LCBD_hel * 1e3, m = "LCBD abundance"), data.frame(year = 2015, habitat = tr15$habitat, tree = tr15$LCBD_hel * 1e3, stem = st15$LCBD_hel * 1e3, m = "LCBD abundance"), data.frame(year = 1985, habitat = tr$habitat, tree = tr$LCBD_hel_occ * 1e3, stem = st$LCBD_hel_occ * 1e3, m = "LCBD occurrence"), data.frame(year = 2015, habitat = tr15$habitat, tree = tr15$LCBD_hel_occ * 1e3, stem = st15$LCBD_hel_occ * 1e3, m = "LCBD occurrence"),
  data.frame(year = 1985, habitat = tr$habitat, tree = tr$T_rel, stem = st$T_rel, m = "T (abundance)"), data.frame(year = 2015, habitat = tr15$habitat, tree = tr15$T_rel, stem = st15$T_rel, m = "T (abundance)"),
  data.frame(year = 1985, habitat = tr$habitat, tree = tr$T_occ, stem = st$T_occ, m = "T (occurrence)"), data.frame(year = 2015, habitat = tr15$habitat, tree = tr15$T_occ, stem = st15$T_occ, m = "T (occurrence)")); cmp$m <- factor(cmp$m, unique(cmp$m))
p6 <- ggplot(cmp, aes(tree, stem, colour = habitat)) + geom_abline(colour = "grey60", linewidth = .3) + geom_point(size = .5, alpha = .7) + facet_grid(year ~ m, scales = "free") + scale_colour_manual(values = hab_col, labels = hab_lab, name = NULL) + labs(x = "Individual tree records (principal analysis)", y = "All stems") + th() + theme(legend.position = "bottom", legend.text = element_text(size = 5.5))
sv(p6 + plot_annotation(tag_levels = "A"), "FigureS6_trees_vs_stems", 9, 5.2); cat("S4-S6 done\n")
